#!/usr/bin/env python3
"""Prepare an explicit, local skill payload; never install, submit or publish.

Python 3.9+ standard library only. Checks are deliberately bounded: basic
frontmatter, ordinary local Markdown links, a narrow secret/path screen and
exact bytes. They do not certify rights, privacy, dependency or agent behavior.
"""
import argparse
import hashlib
import json
from pathlib import Path, PurePosixPath
import posixpath
import re
import stat
from urllib.parse import unquote, urlsplit
import zipfile


MAX_FILE = 16 * 1024 * 1024
NAME = re.compile(r"[a-z0-9]+(?:-[a-z0-9]+)*")
DENIED = {'.git', '.aws', '.ssh', '.codex', '.agents', 'private', 'secrets',
          'credentials', 'customer-data', '__pycache__', 'node_modules'}
PRIVATE_FILES = {'agents.md', 'handoff.md', 'session_context.md'}
SECRET = re.compile(
    rb'-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----|'
    rb'(?:gh[pousr]_|github_pat_)[A-Za-z0-9_]{20,}|'
    rb'sk-[A-Za-z0-9_-]{20,}|AKIA[0-9A-Z]{16}|'
    rb'PRIVATE_CONTEXT_TEST_' rb'SENTINEL|EXPORT_SECRET_TEST_' rb'SENTINEL')
PROVENANCE_LIMIT = 'Caller-supplied commit label; input hashes identify working-tree bytes.'
LIMITS = [
    'Basic metadata and local Markdown checks, not full format validation.',
    'Narrow secret/path screening, not privacy or licensing clearance.',
    'Executable bits normalize to 0755 or 0644; no ownership, ACL or xattr preservation.',
    'No dependency installation, runtime compatibility or behavior evaluation.',
    'No publication, submission or consumer update.']


def digest(data):
    return hashlib.sha256(data).hexdigest()


def strict_json(data):
    def unique(pairs):
        result = {}
        for key, value in pairs:
            if key in result:
                raise ValueError('Duplicate JSON member')
            result[key] = value
        return result
    return json.loads(data, object_pairs_hook=unique)


def relative(value):
    if (not isinstance(value, str) or not value or '\\' in value or ':' in value
            or any(ord(c) < 32 for c in value)):
        raise ValueError('Unsafe relative path')
    path = PurePosixPath(value)
    if (path.is_absolute() or path.as_posix() != value
            or any(p in {'', '.', '..'} for p in value.split('/'))):
        raise ValueError('Unsafe relative path')
    return path


def public_path(value):
    path = relative(value)
    if any(p.lower() in DENIED or p.lower().startswith('.env') for p in path.parts):
        raise ValueError('Private or generated path is not exportable')
    if path.name.lower() in PRIVATE_FILES:
        raise ValueError('Repository instructions/handoffs are not exportable')
    return path


def root_directory(value):
    path = Path(value)
    if not path.is_absolute() or path.is_symlink() or not path.is_dir():
        raise ValueError('An explicit ordinary absolute directory is required')
    return path.resolve()


def source_bytes(root, name):
    path = root
    for part in relative(name).parts:
        path = path / part
        if path.is_symlink():
            raise ValueError('Symlinks are not exportable')
    if not path.is_file() or not path.resolve().is_relative_to(root):
        raise ValueError('Missing or non-regular source file')
    if path.stat().st_size > MAX_FILE:
        raise ValueError('File exceeds the 16 MiB review limit')
    data = path.read_bytes()
    if len(data) > MAX_FILE:
        raise ValueError('File exceeds the 16 MiB review limit')
    return data


def metadata(record):
    if (type(record.get('version')) is not int or record['version'] != 1
            or not isinstance(record.get('name'), str)
            or not NAME.fullmatch(record['name']) or len(record['name']) > 64
            or record.get('kind') not in {'skill', 'plugin'}
            or not isinstance(record.get('source_commit'), str)
            or not re.fullmatch(r'[0-9a-f]{40}', record['source_commit'])):
        raise ValueError('Invalid version, name, kind or source commit')


def config_record(raw):
    record = strict_json(raw)
    if not isinstance(record, dict) or set(record) != {
            'version', 'name', 'kind', 'source_commit', 'files'}:
        raise ValueError('Unexpected export configuration fields')
    metadata(record)
    if not isinstance(record['files'], dict) or not record['files']:
        raise ValueError('Explicit nonempty file mapping required')
    destinations = set()
    for target, source in record['files'].items():
        public_path(target)
        public_path(source)
        if target.casefold() in destinations:
            raise ValueError('Case-colliding destinations')
        destinations.add(target.casefold())
    for target in destinations:
        if any(parent.as_posix() in destinations
               for parent in PurePosixPath(target).parents if parent.as_posix() != '.'):
            raise ValueError('A destination cannot be both file and directory')
    return record


def skill_structure(data):
    text = data.decode('utf-8')
    parts = re.fullmatch(r'---[ \t]*\r?\n(.*?)\r?\n---[ \t]*(?:\r?\n(.*))?', text, re.S)
    if parts is None or not parts[1].strip() or not (parts[2] or '').strip():
        raise ValueError('SKILL.md needs frontmatter delimiters and nonempty instructions')
    # Deliberately no partial YAML parser: target tooling checks keys and semantics.


def inline_targets(text):
    """Read ordinary balanced inline destinations; not a full Markdown parser."""
    for match in re.finditer(r'\]\(', text):
        start, depth, escaped, angle = match.end(), 1, False, False
        for index in range(start, len(text)):
            char = text[index]
            if char == '\n':
                break
            if escaped:
                escaped = False
                continue
            if char == '\\':
                escaped = True
            elif char == '<':
                angle = True
            elif char == '>':
                angle = False
            elif not angle and char in '()':
                depth += 1 if char == '(' else -1
                if depth == 0:
                    yield text[start:index]
                    break


def check_links(payload):
    for name, data in payload.items():
        if not name.lower().endswith('.md'):
            continue
        text = data.decode('utf-8')
        targets = list(inline_targets(text))
        targets += re.findall(r'^\s{0,3}\[[^\]]+\]:\s*(\S+)', text, re.M)
        for target in targets:
            target = target.strip()
            if not target:
                continue  # An empty destination refers to the current document.
            if target.startswith('<'):
                target = target[1:].split('>', 1)[0]
            else:
                target = target.split()[0]
            parsed = urlsplit(target)
            if parsed.scheme in {'https', 'http', 'mailto'}:
                continue
            if parsed.scheme or parsed.netloc:
                raise ValueError('Unsupported Markdown reference scheme')
            route = unquote(parsed.path)
            if not route:
                continue
            if route.startswith('/') or '\\' in route:
                raise ValueError('Absolute Markdown reference')
            destination = posixpath.normpath(posixpath.join(posixpath.dirname(name), route))
            if destination == '.':
                continue  # A contained link to the package's own root directory.
            relative(destination)
            if destination not in payload and not any(
                    p.startswith(destination.rstrip('/') + '/') for p in payload):
                raise ValueError('Local Markdown reference is outside the payload')


def check_payload(record, payload):
    if 'LICENSE' not in payload or not payload['LICENSE'].decode('utf-8').strip():
        raise ValueError('Nonempty LICENSE at the payload root required')
    if record['kind'] == 'skill':
        if 'SKILL.md' not in payload:
            raise ValueError('Root SKILL.md required')
        skill_structure(payload['SKILL.md'])
    else:
        if 'plugin.json' not in payload:
            raise ValueError('Root plugin.json required')
        plugin = strict_json(payload['plugin.json'])
        if not isinstance(plugin, dict) or plugin.get('name') != record['name']:
            raise ValueError('Plugin name mismatch')
        skills = [p for p in payload if re.fullmatch(r'skills/[^/]+/SKILL\.md', p)]
        if not skills:
            raise ValueError('Plugin requires at least one contained skill')
        for path in skills:
            skill_structure(payload[path])
    for data in payload.values():
        if SECRET.search(data):
            raise ValueError('Potential secret/private marker; human review required')
    check_links(payload)


def export(source_root, config, output):
    root = root_directory(source_root)
    raw = Path(config).read_bytes()
    record = config_record(raw)
    output = Path(output)
    if not output.is_absolute() or output.exists() or output.is_symlink():
        raise ValueError('Output must be a new absolute path')
    if not output.parent.is_dir() or output.parent.is_symlink():
        raise ValueError('Output parent must be an existing ordinary directory')
    selected = [root / source for source in record['files'].values()] + [Path(config)]
    if any(path.resolve().is_relative_to(output.resolve()) for path in selected):
        raise ValueError('Output cannot contain selected inputs or its configuration')
    payload = {target: source_bytes(root, source)
               for target, source in record['files'].items()}
    modes = {target: '0755' if (root / source).stat().st_mode & 0o111 else '0644'
             for target, source in record['files'].items()}
    check_payload(record, payload)
    manifest = {key: record[key] for key in ('version', 'name', 'kind', 'source_commit')}
    manifest.update(source_commit_verification=PROVENANCE_LIMIT, config_sha256=digest(raw),
                    limitations=LIMITS, files={
                        name: {'source': record['files'][name], 'sha256': digest(payload[name]),
                               'mode': modes[name]}
                        for name in sorted(payload)})
    # Validation finishes before claiming a fresh output directory. Never overwrite.
    output.mkdir(mode=0o700)
    stage = output / 'payload'
    stage.mkdir()
    with zipfile.ZipFile(output / 'skill.zip', 'x', compression=zipfile.ZIP_STORED) as archive:
        for name in sorted(payload):
            destination = stage / name
            destination.parent.mkdir(parents=True, exist_ok=True)
            with destination.open('xb') as handle:
                handle.write(payload[name])
            destination.chmod(int(modes[name], 8))
            entry = zipfile.ZipInfo(name, date_time=(1980, 1, 1, 0, 0, 0))
            entry.create_system = 3
            entry.external_attr = (stat.S_IFREG | int(modes[name], 8)) << 16
            archive.writestr(entry, payload[name])
    with (output / 'manifest.json').open('x', encoding='utf-8') as handle:
        json.dump(manifest, handle, indent=2, sort_keys=True)
        handle.write('\n')
    verify(output / 'manifest.json', archive=output / 'skill.zip')
    return {'status': 'prepared', 'file_count': len(payload), 'limitations': LIMITS}


def manifest_files(path):
    record = strict_json(Path(path).read_bytes())
    if not isinstance(record, dict) or set(record) != {
            'version', 'name', 'kind', 'source_commit', 'source_commit_verification',
            'config_sha256', 'limitations', 'files'}:
        raise ValueError('Unexpected manifest fields')
    metadata(record)
    if (record['source_commit_verification'] != PROVENANCE_LIMIT
            or record['limitations'] != LIMITS
            or not isinstance(record['config_sha256'], str)
            or not re.fullmatch(r'[0-9a-f]{64}', record['config_sha256'])
            or not isinstance(record['files'], dict) or not record['files']):
        raise ValueError('Invalid manifest provenance')
    files = {}
    for name, entry in record['files'].items():
        public_path(name)
        if (not isinstance(entry, dict) or set(entry) != {'source', 'sha256', 'mode'}
                or not isinstance(entry['sha256'], str)
                or not re.fullmatch(r'[0-9a-f]{64}', entry['sha256'])
                or entry['mode'] not in {'0644', '0755'}):
            raise ValueError('Invalid file evidence')
        public_path(entry['source'])
        files[name] = {'sha256': entry['sha256'], 'mode': entry['mode']}
    return files


def verify(manifest, archive=None, installed_root=None):
    expected = manifest_files(manifest)
    actual = {}
    if (archive is None) == (installed_root is None):
        raise ValueError('Choose one archive or installed directory')
    if archive is not None:
        with zipfile.ZipFile(archive) as handle:
            for entry in handle.infolist():
                public_path(entry.filename)
                mode = entry.external_attr >> 16
                if (entry.filename in actual or entry.is_dir()
                        or stat.S_IFMT(mode) not in {0, stat.S_IFREG}
                        or entry.file_size > MAX_FILE):
                    raise ValueError('Duplicate, oversized or non-regular ZIP entry')
                if entry.filename not in expected:
                    raise ValueError('Unexpected ZIP entry')
                actual[entry.filename] = {'sha256': digest(handle.read(entry)),
                                          'mode': format(stat.S_IMODE(mode), '04o')}
    else:
        root = root_directory(installed_root)
        for path in root.rglob('*'):
            if path.is_symlink():
                raise ValueError('Installed links are not exact file evidence')
            if path.is_dir():
                continue
            name = path.relative_to(root).as_posix()
            public_path(name)
            actual[name] = {'sha256': digest(source_bytes(root, name)),
                            'mode': format(stat.S_IMODE(path.stat().st_mode), '04o')}
    if actual != expected:
        raise ValueError('Inventory, bytes or file modes differ from reviewed manifest')
    return {'status': 'verified', 'file_count': len(actual),
            'scope': 'Exact local bytes and normalized modes only; no runtime or publication claim.'}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    modes = parser.add_subparsers(dest='mode', required=True)
    prepare = modes.add_parser('export')
    prepare.add_argument('--source-root', type=Path, required=True)
    prepare.add_argument('--config', type=Path, required=True)
    prepare.add_argument('--output', type=Path, required=True)
    check = modes.add_parser('verify')
    check.add_argument('--manifest', type=Path, required=True)
    target = check.add_mutually_exclusive_group(required=True)
    target.add_argument('--archive', type=Path)
    target.add_argument('--installed-root', type=Path)
    args = parser.parse_args()
    try:
        result = (export(args.source_root, args.config, args.output) if args.mode == 'export'
                  else verify(args.manifest, args.archive, args.installed_root))
    except (ValueError, OSError, UnicodeError, TypeError, zipfile.BadZipFile) as error:
        # Do not echo input content, paths or credential values in diagnostic output.
        parser.exit(2, 'Blocked: ' + (str(error) if type(error) is ValueError else
                                    type(error).__name__) + '\n')
    print(json.dumps(result, sort_keys=True))


if __name__ == '__main__':
    main()
#!/usr/bin/env python3
"""
Quick validation script for skills - minimal version
"""

import re
import sys
from pathlib import Path

import yaml

MAX_SKILL_NAME_LENGTH = 64


def validate_skill(skill_path):
    """Basic validation of a skill"""
    skill_path = Path(skill_path)

    skill_md = skill_path / "SKILL.md"
    if not skill_md.exists():
        return False, "SKILL.md not found"

    content = skill_md.read_text()
    if not content.startswith("---"):
        return False, "No YAML frontmatter found"

    match = re.match(r"^---\n(.*?)\n---", content, re.DOTALL)
    if not match:
        return False, "Invalid frontmatter format"

    frontmatter_text = match.group(1)

    try:
        frontmatter = yaml.safe_load(frontmatter_text)
        if not isinstance(frontmatter, dict):
            return False, "Frontmatter must be a YAML dictionary"
    except yaml.YAMLError as e:
        return False, f"Invalid YAML in frontmatter: {e}"

    allowed_properties = {"name", "description", "license", "allowed-tools", "metadata"}

    unexpected_keys = set(frontmatter.keys()) - allowed_properties
    if unexpected_keys:
        allowed = ", ".join(sorted(allowed_properties))
        unexpected = ", ".join(sorted(unexpected_keys))
        return (
            False,
            f"Unexpected key(s) in SKILL.md frontmatter: {unexpected}. Allowed properties are: {allowed}",
        )

    if "name" not in frontmatter:
        return False, "Missing 'name' in frontmatter"
    if "description" not in frontmatter:
        return False, "Missing 'description' in frontmatter"

    name = frontmatter.get("name", "")
    if not isinstance(name, str):
        return False, f"Name must be a string, got {type(name).__name__}"
    name = name.strip()
    if name:
        if not re.match(r"^[a-z0-9-]+$", name):
            return (
                False,
                f"Name '{name}' should be hyphen-case (lowercase letters, digits, and hyphens only)",
            )
        if name.startswith("-") or name.endswith("-") or "--" in name:
            return (
                False,
                f"Name '{name}' cannot start/end with hyphen or contain consecutive hyphens",
            )
        if len(name) > MAX_SKILL_NAME_LENGTH:
            return (
                False,
                f"Name is too long ({len(name)} characters). "
                f"Maximum is {MAX_SKILL_NAME_LENGTH} characters.",
            )

    description = frontmatter.get("description", "")
    if not isinstance(description, str):
        return False, f"Description must be a string, got {type(description).__name__}"
    description = description.strip()
    if description.startswith("[TODO:"):
        return False, "Description contains an unfinished TODO placeholder"
    if description:
        if "<" in description or ">" in description:
            return False, "Description cannot contain angle brackets (< or >)"
        if len(description) > 1024:
            return (
                False,
                f"Description is too long ({len(description)} characters). Maximum is 1024 characters.",
            )

    body = content[match.end() :]
    fence_marker = None
    fence_length = 0
    for line in body.splitlines():
        fence = re.match(r"^[ \t]*(?:(?:[-+*]|\d+[.)])[ \t]+)?(`{3,}|~{3,})(.*)$", line)
        if fence:
            marker = fence.group(1)
            if fence_marker is None:
                fence_marker = marker[0]
                fence_length = len(marker)
            elif (
                marker[0] == fence_marker
                and len(marker) >= fence_length
                and not fence.group(2).strip()
            ):
                fence_marker = None
                fence_length = 0
            continue

        if fence_marker is None and re.fullmatch(
            r"[ ]{0,3}\[TODO:[^\n]*\][ \t]*", line
        ):
            return False, "Skill instructions contain an unfinished TODO placeholder"

    return True, "Skill is valid!"


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python quick_validate.py <skill_directory>")
        sys.exit(1)

    valid, message = validate_skill(sys.argv[1])
    print(message)
    sys.exit(0 if valid else 1)

#!/usr/bin/env python3
"""Flag selected prose for editorial review; never score or rewrite writing.

Only UTF-8 .md and .txt files are supported. Findings are review candidates,
not errors, evidence of AI authorship, or a judgment of literary quality.
"""
from __future__ import annotations

import argparse
from bisect import bisect_right
from collections import defaultdict
from dataclasses import asdict, dataclass
import json
import os
from pathlib import Path
import re
import sys
from typing import Iterable, Mapping, Sequence


TERMS = (
    "tranche", "gate", "delve", "tapestry", "testament", "beacon",
    "revolutionize", "moreover", "furthermore",
)
STOCK_PHRASES = (
    "in today's fast-paced world", "it is worth noting",
    "in conclusion", "to summarize",
)
EXCLUDED_DIRS = frozenset({
    ".git", ".hg", ".svn", ".agents", ".codex", "node_modules",
    "venv", ".venv", "env", ".env", "build", "dist", "target", "out",
    ".next", ".nuxt", ".output", "coverage", "htmlcov", ".cache",
    "__pycache__", ".pytest_cache", ".mypy_cache", ".ruff_cache", ".tox",
})
WORD_RE = re.compile(r"[^\W_]+(?:['’][^\W_]+)*", re.UNICODE)
TERM_RE = re.compile(
    r"(?<!\w)(?:" + "|".join(TERMS) + r")(?!\w)", re.IGNORECASE
)
FENCE_RE = re.compile(r"^ {0,3}(`{3,}|~{3,})(.*)$")
HEADING_RE = re.compile(r"^ {0,3}(#{1,6})[ \t]+(.*)$")
LIST_RE = re.compile(r"^ {0,3}(?:[-+*]|\d+[.)])[ \t]+")
REF_RE = re.compile(r"^ {0,3}\[([^\]\n]+)\]:[^\n]*(?:\n|$)", re.M)
URL_RE = re.compile(
    r"<[A-Za-z][A-Za-z0-9+.-]*:[^<>\s]*>"
    r"|\b(?:[A-Za-z][A-Za-z0-9+.-]*://|www\.)[^\s<>]+",
    re.IGNORECASE,
)


@dataclass(frozen=True)
class Finding:
    path: str
    line: int
    rule: str
    excerpt: str


class LintError(Exception):
    """An input could not be read safely as a supported prose file."""


def _blank(text: str) -> str:
    """Remove content without moving original line/character positions."""
    return "".join("\n" if char == "\n" else " " for char in text)


def _normal(text: str) -> str:
    text = text.replace("’", "'")
    for dash in ("‐", "‑", "–"):
        text = text.replace(dash, "-")
    return " ".join(text.casefold().split())


def _excerpt(text: str) -> str:
    compact = " ".join(text.split())
    return compact if len(compact) <= 160 else compact[:157] + "..."


def _term_excerpt(text: str, match: re.Match) -> str:
    line_start = text.rfind("\n", 0, match.start()) + 1
    line_end = text.find("\n", match.end())
    if line_end < 0:
        line_end = len(text)
    left = max(line_start, match.start() - 65)
    right = min(line_end, match.end() + 75)
    excerpt = text[left:right]
    if left > line_start:
        excerpt = "..." + excerpt
    if right < line_end:
        excerpt += "..."
    return _excerpt(excerpt)


def _block_start(line: str) -> bool:
    return bool(
        HEADING_RE.match(line) or LIST_RE.match(line)
        or FENCE_RE.match(line)
        or re.match(r"^ {0,3}(?:\*\s*){3,}$|^ {0,3}(?:-\s*){3,}$"
                    r"|^ {0,3}(?:_\s*){3,}$", line.rstrip())
    )


def visible_prose(text: str) -> str:
    """Mask common Markdown non-prose while retaining source positions.

    This is a deliberately small scanner, not a full CommonMark parser.
    It handles fenced/inline code, front matter, comments, blockquotes
    (including ordinary lazy continuations), and link destinations.
    """
    if text.startswith("\ufeff"):
        text = " " + text[1:]
    lines = text.splitlines(keepends=True)
    if lines and lines[0].strip() == "---":
        stop = None
        for index in range(1, len(lines)):
            if lines[index].strip() in {"---", "..."}:
                stop = index + 1
                break
        # An unmatched opening may be an ordinary thematic break.
        if stop is not None:
            lines[:stop] = [_blank(line) for line in lines[:stop]]
    text = "".join(lines)
    chars = list(text)
    fence_char, fence_size = "", 0
    in_quote = False
    offset = 0
    for source_line in text.splitlines(keepends=True):
        stop = offset + len(source_line)
        line = "".join(chars[offset:stop])
        fence = FENCE_RE.match(line.rstrip("\r\n"))
        if fence_char:
            chars[offset:stop] = _blank(line)
            if (fence and fence[1][0] == fence_char
                    and len(fence[1]) >= fence_size
                    and not fence[2].strip()):
                fence_char, fence_size = "", 0
        elif re.match(r"^ {0,3}>", line):
            content = re.sub(r"^ {0,3}>[ \t]?", "", line)
            in_quote = bool(content.strip())
            chars[offset:stop] = _blank(line)
        elif in_quote and line.strip() and not _block_start(line):
            chars[offset:stop] = _blank(line)
        else:
            in_quote = False
            if fence and not (fence[1][0] == "`" and "`" in fence[2]):
                fence_char, fence_size = fence[1][0], len(fence[1])
                chars[offset:stop] = _blank(line)
            else:
                cursor = offset
                while cursor < stop:
                    if "".join(chars[cursor:cursor + 4]) == "<!--":
                        end = text.find("-->", cursor + 4)
                        end = len(text) if end < 0 else end + 3
                        chars[cursor:end] = _blank(text[cursor:end])
                        cursor = end
                    elif chars[cursor] == "`":
                        opening = re.match(r"`+", text[cursor:])[0]
                        back = cursor - 1
                        while back >= 0 and text[back] == "\\":
                            back -= 1
                        escaped = (cursor - back - 1) % 2 == 1
                        end = None
                        if not escaped:
                            for closing in re.finditer(
                                    r"`+", text[cursor + len(opening):]):
                                close_start = (cursor + len(opening)
                                               + closing.start())
                                between = text[cursor:close_start]
                                if re.search(r"\n[ \t]*\n", between):
                                    break
                                if len(closing[0]) == len(opening):
                                    end = close_start + len(closing[0])
                                    break
                        if end is not None:
                            chars[cursor:end] = _blank(text[cursor:end])
                            cursor = end
                        else:
                            cursor += len(opening)
                    else:
                        cursor += 1
        offset = stop
    text = "".join(chars)

    definitions = {_normal(match[1]) for match in REF_RE.finditer(text)}
    text = REF_RE.sub(lambda match: _blank(match[0]), text)
    chars = list(text)
    # Keep visible [labels]; mask balanced (...) destinations and titles.
    for opening in re.finditer(r"\]\(", text):
        start = opening.end() - 1
        if chars[start] == " ":
            continue
        depth, cursor, quote, angle = 1, start + 1, "", False
        while cursor < len(text) and depth:
            char = text[cursor]
            if char == "\\":
                cursor += 2
                continue
            if quote:
                if char == quote:
                    quote = ""
            elif angle:
                if char == ">":
                    angle = False
            elif char == "<":
                angle = True
            elif char in "\"'" and text[cursor - 1].isspace():
                quote = char
            elif char == "(":
                depth += 1
            elif char == ")":
                depth -= 1
            cursor += 1
        if depth == 0:
            chars[start:cursor] = _blank(text[start:cursor])
    text = "".join(chars)
    text = re.sub(
        r"(?<=\])\s*\[([^\]\n]*)\]",
        lambda match: _blank(match[0])
        if not match[1] or _normal(match[1]) in definitions else match[0],
        text,
    )
    return URL_RE.sub(lambda match: _blank(match[0]), text)


def _paragraphs(text: str) -> list[tuple[int, str]]:
    paragraphs = []
    pending = []
    first = 0

    def flush() -> None:
        if pending:
            paragraph = " ".join(pending)
            if len(WORD_RE.findall(paragraph)) >= 20:
                paragraphs.append((first, paragraph))
            pending.clear()

    for number, line in enumerate(text.splitlines(), 1):
        if not line.strip() or HEADING_RE.match(line):
            flush()
            continue
        # Separate list entries instead of treating an entire list as prose.
        if LIST_RE.match(line):
            flush()
            line = LIST_RE.sub("", line, count=1)
        if not pending:
            first = number
        pending.append(line.strip())
    flush()
    return paragraphs


def lint_documents(
    documents: Mapping[str, str], *, allow_terms: Iterable[str] = (),
    check_heading_sequences: bool = False,
) -> list[Finding]:
    """Review in-memory path/text pairs, including cross-document repeats.

    Repeated paragraphs need at least 20 words and two distinct documents.
    Optional trailing H2 sequences need at least 4 headings in 3 documents.
    Allow terms suppress exact word/phrase rules only, not repetition rules.
    """
    allowed = {_normal(term) for term in allow_terms}
    findings = []
    paragraphs = defaultdict(list)
    suffixes = defaultdict(list)
    for path, original in sorted(documents.items()):
        text = visible_prose(original)
        starts = [0] + [m.end() for m in re.finditer("\n", text)]
        lines = text.splitlines()
        for match in TERM_RE.finditer(text):
            if _normal(match[0]) not in allowed:
                line = bisect_right(starts, match.start())
                findings.append(Finding(path, line, "word-choice",
                                        _term_excerpt(text, match)))
        for phrase in STOCK_PHRASES:
            if _normal(phrase) in allowed:
                continue
            pattern = r"\s+".join(re.escape(word)
                                     for word in phrase.split())
            pattern = pattern.replace("'", "['’]")
            pattern = pattern.replace(r"\-", "[-‐‑–]")
            for match in re.finditer(r"(?<!\w)" + pattern + r"(?!\w)",
                                     text, re.IGNORECASE):
                findings.append(Finding(
                    path, bisect_right(starts, match.start()),
                    "stock-phrase", _excerpt(match[0]),
                ))
        for line, paragraph in _paragraphs(text):
            paragraphs[_normal(paragraph)].append((path, line, paragraph))
        if check_heading_sequences:
            headings = []
            for number, line in enumerate(lines, 1):
                match = HEADING_RE.match(line)
                if match and match[1] == "##":
                    title = re.sub(r"\s+#+\s*$", "", match[2]).strip()
                    if title:
                        headings.append((number, _normal(title)))
            for length in range(4, len(headings) + 1):
                suffix = headings[-length:]
                suffixes[tuple(title for _, title in suffix)].append(
                    (path, suffix[0][0]))
    for copies in paragraphs.values():
        if len({path for path, _, _ in copies}) >= 2:
            findings.extend(Finding(path, line, "repeated-paragraph",
                                    _excerpt(paragraph))
                            for path, line, paragraph in copies)
    # Report only the longest qualifying suffix in each document.
    longest = {}
    for sequence, copies in suffixes.items():
        if len({path for path, _ in copies}) < 3:
            continue
        for path, line in copies:
            if path not in longest or len(sequence) > len(longest[path][1]):
                longest[path] = (line, sequence)
    findings.extend(Finding(path, line, "repeated-h2-sequence",
                            _excerpt(" → ".join(sequence)))
                    for path, (line, sequence) in longest.items())
    return sorted(set(findings), key=lambda item:
                  (item.path, item.line, item.rule, item.excerpt))


def _safe_absolute(path: Path) -> Path:
    absolute = path.expanduser().absolute()
    cursor = Path(absolute.anchor)
    for part in absolute.parts[1:]:
        cursor /= part
        if cursor.is_symlink():
            raise LintError(f"Symlink input is not followed: {path}")
    return Path(os.path.abspath(absolute))


def collect_paths(inputs: Sequence[str | Path]) -> list[Path]:
    """Collect supported regular files; nested symlinks/artifacts are skipped."""
    found = set()

    def walk_error(error: OSError) -> None:
        raise LintError(str(error)) from error

    for raw in inputs:
        try:
            path = _safe_absolute(Path(raw))
            if not path.exists():
                raise LintError(f"Input does not exist: {raw}")
            if any(part.casefold() in EXCLUDED_DIRS for part in path.parts):
                continue
            if path.is_file():
                if path.suffix.lower() not in {".md", ".txt"}:
                    raise LintError(f"Unsupported input (use .md/.txt): {raw}")
                found.add(path)
            elif path.is_dir():
                for base, dirs, files in os.walk(path, followlinks=False,
                                                  onerror=walk_error):
                    dirs[:] = sorted(name for name in dirs
                                     if name.casefold() not in EXCLUDED_DIRS
                                     and not (Path(base) / name).is_symlink())
                    for name in sorted(files):
                        candidate = Path(base) / name
                        if (candidate.suffix.lower() in {".md", ".txt"}
                                and not candidate.is_symlink()
                                and candidate.is_file()):
                            found.add(candidate)
            else:
                raise LintError(f"Not a regular file or directory: {raw}")
        except OSError as error:
            raise LintError(f"Cannot inspect {raw}: {error}") from error
    return sorted(found, key=str)


def _read_documents(paths: Sequence[Path]) -> dict[str, str]:
    documents = {}
    for path in paths:
        try:
            documents[str(path)] = path.read_text(encoding="utf-8-sig")
        except (OSError, UnicodeError) as error:
            raise LintError(f"Cannot read {path}: {error}") from error
    return documents


def lint_paths(
    inputs: Sequence[str | Path], *, allow_terms: Iterable[str] = (),
    check_heading_sequences: bool = False,
) -> list[Finding]:
    """Read supported UTF-8 inputs, raising LintError for input/read errors."""
    return lint_documents(_read_documents(collect_paths(inputs)),
                          allow_terms=allow_terms,
                          check_heading_sequences=check_heading_sequences)


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("paths", nargs="+", help=".md/.txt files or directories")
    parser.add_argument("--format", choices=("text", "json"), default="text")
    parser.add_argument("--allow-term", action="append", default=[],
                        help="allow an exact word or stock phrase; repeatable")
    parser.add_argument("--fail-on-findings", action="store_true",
                        help="exit 1 for findings instead of the default 0")
    parser.add_argument("--check-heading-sequences", action="store_true",
                        help="review repeated trailing H2 sequences")
    args = parser.parse_args(argv)
    try:
        paths = collect_paths(args.paths)
        findings = lint_documents(
            _read_documents(paths), allow_terms=args.allow_term,
            check_heading_sequences=args.check_heading_sequences)
    except LintError as error:
        print(f"prose_lint: {error}", file=sys.stderr)
        return 2
    if args.format == "json":
        print(json.dumps({"files_checked": len(paths),
                          "findings": [asdict(item) for item in findings]},
                         ensure_ascii=False, indent=2))
    elif findings:
        for finding in findings:
            print(f"{finding.path}:{finding.line}: {finding.rule}: "
                  f"{finding.excerpt}")
        print(f"{len(findings)} review candidate(s); editorial review required.")
    else:
        print("No findings from the selected checks; this is not a quality assessment.")
    return 1 if findings and args.fail_on_findings else 0


if __name__ == "__main__":
    raise SystemExit(main())

